const cfg = $('Config').first().json;
const dados = $('Dados').first().json;
const TEST_MODE = String(cfg.TEST_MODE) === 'true';
const ini = Number(cfg.JANELA_INICIO);
const fim = Number(cfg.JANELA_FIM);
const hora = DateTime.now().setZone('America/Sao_Paulo').hour;
const dentro = (hora >= ini || hora < fim);
return [{ json: { ...dados, _passaGate: TEST_MODE || dentro } }];

const base64 = $input.first().json.base64;
const buffer = Buffer.from(base64, 'base64');
return [{ json: $input.first().json, binary: { data: await this.helpers.prepareBinaryData(buffer, 'audio.ogg', 'audio/ogg') } }];

const mh = $('Monta Historico').first().json || {};
return [{ json: {
  output: mh.output || '',
  emergencia: mh.emergencia === true,
  modo: mh.modo || null,
  motivo_alerta: mh.motivo_alerta || null,
  classificacao_real: mh.classificacao_real || null,
  criterio_disparado: mh.criterio_disparado || null,
  intent: mh.intent || null
} }];

const texto = String($('Detecta Emergencia').first().json.output || '').trim();
const limite = 320;
const minimoParaPontuacao = Math.floor(limite * 0.55);

function quebrarSemCortarPalavra(trecho) {
  const partes = [];
  let restante = trecho.trim();

  while (restante.length > limite) {
    let corte = -1;
    const janela = restante.slice(0, limite + 1);

    // Prioriza fim de frase perto do limite.
    for (let i = minimoParaPontuacao; i < janela.length; i++) {
      if (/[.!?]/.test(janela[i]) && (i === janela.length - 1 || /\s/.test(janela[i + 1]))) {
        corte = i + 1;
      }
    }

    // Sem fim de frase adequado, corta no ultimo espaco.
    if (corte < 1) corte = janela.lastIndexOf(' ');
    if (corte < 1) corte = limite;

    const parte = restante.slice(0, corte).trim();
    if (parte) partes.push(parte);
    restante = restante.slice(corte).trim();
  }

  if (restante) partes.push(restante);
  return partes;
}

const paragrafos = texto.split(/\n+/).map(p => p.trim()).filter(Boolean);
const mensagens = paragrafos.flatMap(quebrarSemCortarPalavra);
const finais = mensagens.length ? mensagens : [texto];

return finais.map(message => ({ json: { message } }));

const current = $('Redis Get 2').first().json.propertyName || [];
const currentLen = current.length;
const prevRaw = $json.prevCount;
const prevLen = prevRaw ? parseInt(prevRaw, 10) : 0;
return [{ json: { stillGrowing: currentLen > prevLen, currentLen, messages: current } }];

const raw = $('Ler Historico').first().json;
let arr = raw && raw.historico_mensagens;
if (typeof arr === 'string') { try { arr = JSON.parse(arr); } catch (e) { arr = []; } }
if (!Array.isArray(arr)) arr = [];
const janela = arr.slice(-6);
let texto = '';
for (const m of janela) {
  if (!m) continue;
  const role = m.role === 'assistant' ? 'Assistant' : 'User';
  texto += role + ': ' + (m.content || '') + '\n\n';
}
texto = texto.trim();
if (!texto) texto = 'Nenhuma conversa anterior. Esta e a primeira interacao.';
return [{ json: { historico_texto: texto, historico_array: arr } }];

const su = $('Set_User').first().json;
let erro = 'erro desconhecido';
try {
  const e = $json.error;
  erro = typeof e === 'string' ? e : ((e && e.message) || JSON.stringify(e) || erro);
} catch (x) {}

return [{ json: {
  classificacao: null,
  classificacao_real: 'falha_tecnica',
  emergencia: false,
  modo: 'falha_tecnica',
  criterio_disparado: null,
  confianca: null,
  precisa_mais_info: false,
  intent: null,
  tem_pergunta_info: false,
  motivo_alerta: 'Falha tecnica na triagem automatica (' + erro + '). Revisao manual necessaria para o tutor ' + (su.user_name || '?') + ' (' + (su.user_number || '?') + '). Relato: ' + (su.user_message || '?'),
  output: 'Tivemos uma instabilidade no atendimento automatico e nao consegui concluir a triagem. Por seguranca, entre em contato diretamente com o plantao. Se o seu pet estiver com dificuldade para respirar, inconsciente, convulsionando, sangrando muito ou piorando rapido, procure atendimento veterinario de emergencia imediatamente.',
  _captura: null
} }];

const j = $input.first().json || {};
const emergencia = j.emergencia === true;
const modo = j.modo || (emergencia ? 'emergencia' : 'final');
return [{ json: {
  classificacao: (j.classificacao === undefined ? null : j.classificacao),
  classificacao_real: j.classificacao_real || (emergencia ? 'emergencia' : 'nao_emergencia'),
  emergencia: emergencia,
  modo: modo,
  criterio_disparado: (j.criterio_disparado === undefined ? null : j.criterio_disparado),
  confianca: j.confianca || null,
  precisa_mais_info: j.precisa_mais_info === true,
  intent: (j.intent === undefined ? null : j.intent),
  tem_pergunta_info: j.tem_pergunta_info === true,
  motivo_alerta: (j.motivo_alerta === undefined ? null : j.motivo_alerta),
  output: (j.output || '').toString(),
  _captura: (j._captura === undefined ? null : j._captura)
} }];

const su = $('Set_User').first().json;
const fh = $('FORMATA_HISTORICO').first().json || {};
const pp = $('Pos-Processo').first().json || {};
let arr = Array.isArray(fh.historico_array) ? fh.historico_array.slice() : [];
let msgId = '';
try { msgId = ($('Entrada Unificada').first().json.body.data.key.id) || ''; } catch (e) {}
const jaTem = !!msgId && arr.some(function (m) { return m && m.msg_id === msgId; });
const nowIso = new Date().toISOString();
if (!jaTem) {
  const turnoUser = { role: 'user', content: su.user_message, ts: nowIso };
  if (msgId) turnoUser.msg_id = msgId;
  arr.push(turnoUser);
  arr.push({ role: 'assistant', content: pp.output || '', ts: nowIso });
}
return [{ json: {
  historico_final: arr,
  classificacao_real: pp.classificacao_real || null,
  output: pp.output || '',
  emergencia: pp.emergencia === true,
  modo: pp.modo || null,
  motivo_alerta: pp.motivo_alerta || null,
  criterio_disparado: pp.criterio_disparado || null,
  intent: pp.intent || null
} }];

const su = $('Set_User').first().json;
const pp = $('Pos-Processo').first().json || {};
const cap = pp._captura;
if (!cap || !cap.classificador) return [];
const nome = (su.user_name || '').trim();
function scrub(v) {
  let s = typeof v === 'string' ? v : JSON.stringify(v);
  if (!s) return v;
  if (nome && nome.length > 1) s = s.split(nome).join('[REDACTED_NOME]');
  s = s.replace(/\b\d{10,13}\b/g, '[REDACTED_FONE]');
  s = s.replace(/\(\d{2}\)\s?\d{4,5}-?\d{4}/g, '[REDACTED_FONE]');
  s = s.replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, '[REDACTED_EMAIL]');
  s = s.replace(/\d{3}\.?\d{3}\.?\d{3}-?\d{2}/g, '[REDACTED_CPF]');
  if (typeof v === 'string') return s;
  try { return JSON.parse(s); } catch (e) { return s; }
}
const rows = [];
rows.push({ ai_node_name: 'Classificador', input_anonymized: scrub(cap.classificador.input || {}), output_anonymized: scrub(cap.classificador.output_raw || {}) });
if (cap.compositor && cap.compositor.nome && cap.compositor.nome !== 'template_horario') {
  rows.push({ ai_node_name: cap.compositor.nome, input_anonymized: scrub(cap.compositor.input || {}), output_anonymized: scrub(cap.compositor.output_raw || '') });
}
return rows.map(function (r) { return { json: r }; });

// Unifica webhook direto e chamada via Webhook Central.
const item = $input.first().json || {};
let body = item.body;

if (body) {
  const data = body.data || {};
  const key = data.key || {};
  const normalizedRemoteJid = item.number
    ? item.number + '@s.whatsapp.net'
    : (key.remoteJid || item.remoteJid || '');

  body = {
    ...body,
    data: {
      ...data,
      key: {
        ...key,
        remoteJid: normalizedRemoteJid
      }
    }
  };
} else {
  const remoteJid = item.remoteJid || (item.number ? item.number + '@s.whatsapp.net' : '');
  body = {
    instance: item.instance || '',
    data: {
      key: { remoteJid, fromMe: false, id: item.msg_id || undefined },
      message: { conversation: item.mensagem_atual || '' },
      pushName: item.nome || '',
      messageType: item.messageType || 'conversation'
    }
  };
}

return [{ json: { body } }];

const j = $input.first().json || {};
const cap = j._captura && j._captura.gate_contextual;
if (!cap) return [];
function scrub(v) {
  let s = typeof v === 'string' ? v : JSON.stringify(v);
  if (!s) return v;
  s = s.replace(/\b\d{10,13}\b/g, '[REDACTED_FONE]');
  s = s.replace(/\(\d{2}\)\s?\d{4,5}-?\d{4}/g, '[REDACTED_FONE]');
  s = s.replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, '[REDACTED_EMAIL]');
  s = s.replace(/\d{3}\.?\d{3}\.?\d{3}-?\d{2}/g, '[REDACTED_CPF]');
  if (typeof v === 'string') return s;
  try { return JSON.parse(s); } catch (e) { return s; }
}
return [{ json: {
  ai_node_name: 'Gate Contextual',
  input_anonymized: scrub(cap.input || {}),
  output_anonymized: scrub(cap.output_raw || {}),
  decisao_contextual: j.decisao_contextual || null
} }];
